import{_ as t,o as a,c as i,a3 as o}from"./chunks/framework.CHYjUC2p.js";const u=JSON.parse('{"title":"Project Pitch: RFC 9111 CDN Caching Proxy","description":"","frontmatter":{},"headers":[],"relativePath":"00b-project-pitch.md","filePath":"00b-project-pitch.md"}'),c={name:"00b-project-pitch.md"};function s(r,e,n,d,l,h){return a(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="project-pitch-rfc-9111-cdn-caching-proxy" tabindex="-1">Project Pitch: RFC 9111 CDN Caching Proxy <a class="header-anchor" href="#project-pitch-rfc-9111-cdn-caching-proxy" aria-label="Permalink to &quot;Project Pitch: RFC 9111 CDN Caching Proxy&quot;">​</a></h1><h2 id="_30-second-elevator-pitch" tabindex="-1">30-Second Elevator Pitch <a class="header-anchor" href="#_30-second-elevator-pitch" aria-label="Permalink to &quot;30-Second Elevator Pitch&quot;">​</a></h2><blockquote><p>&quot;I engineered <strong>17-CDN-Caching-Proxy</strong>, an industrial-grade RFC 9111 compliant reverse caching proxy built with TypeScript and Node.js stream pipelines. Siting at the network edge, it intercepts client requests, executes sub-millisecond cache lookups across in-memory and disk segments, and delivers up to 95% origin bandwidth offload. It solves cache stampedes via atomic request coalescing, handles video streaming with RFC 7233 byte-range slicing, performs on-the-fly streaming Brotli compression, and supports instant Surrogate-Key tag purges with an immutable cryptographic audit trail.&quot;</p></blockquote><hr><h2 id="_2-minute-technical-interview-pitch" tabindex="-1">2-Minute Technical Interview Pitch <a class="header-anchor" href="#_2-minute-technical-interview-pitch" aria-label="Permalink to &quot;2-Minute Technical Interview Pitch&quot;">​</a></h2><blockquote><p>&quot;When scaling high-traffic distributed web systems, uncached traffic creates origin database saturation, massive cloud egress bills, and elevated p99 user latencies.</p><p>To solve this, I designed and implemented <strong>17-CDN-Caching-Proxy</strong>, a complete RFC 9111 compliant reverse-caching edge proxy paired with a Next.js 14 operational dashboard.</p><p>At the core of the proxy in <code>src/proxy/index.ts</code> and <code>src/cache/lookup.ts</code>, incoming requests are parsed and canonicalized into SHA-256 cache keys. The key generator normalizes URL paths, sorts query parameters deterministically, and isolates variant representations using secondary keys calculated from HTTP <code>Vary</code> headers such as <code>Accept-Encoding</code>.</p><p>To eliminate catastrophic &#39;thundering herd&#39; cache stampedes when popular content expires, I developed a Single-Flight Request Coalescer in <code>src/proxy/coalesce.ts</code>. When hundreds of concurrent requests miss the cache for the same resource, the first request is elected leader and dispatched to the upstream origin, while all subsequent requests join an in-flight queue. Once the origin stream arrives, it is fanned out to all waiting clients and piped simultaneously into the cache store using zero-copy stream splitting.</p><p>The storage subsystem in <code>src/cache/</code> features a two-tier architecture: a memory-segmented LRU store bounded by tenant quotas and total byte limits, backed by a persistent disk store with background segment compaction. Freshness is strictly calculated per RFC 9111, honoring <code>s-maxage</code>, <code>max-age</code>, <code>stale-while-revalidate</code>, and conditional HTTP 304 revalidations via <code>ETag</code> and <code>If-None-Match</code>.</p><p>For dynamic content invalidation, I built a Surrogate-Key tag index in <code>src/purge/</code> that invalidates thousands of catalog items within 5 milliseconds, backed by a SHA-256 tamper-evident audit log. The system is validated by 151 Vitest test suites and 1,064 assertions covering protocol edge cases, client socket disconnections, and zero memory leaks under 1,000 consecutive 1 MB requests.&quot;</p></blockquote>',6)])])}const g=t(c,[["render",s]]);ex